-- Donnees FICTIVES pour le projet sql-spark : des magasins et leurs ventes.
--
-- Ce fichier est execute automatiquement au premier demarrage de PostgreSQL
-- ET de MySQL (dossier /docker-entrypoint-initdb.d). Il n'utilise que du SQL
-- standard, compris par les deux bases.

CREATE TABLE magasins (
  magasin_id  INT PRIMARY KEY,
  nom         VARCHAR(50),
  ville       VARCHAR(50)
);

CREATE TABLE ventes (
  vente_id    INT PRIMARY KEY,
  magasin_id  INT,
  date_vente  DATE,
  montant     DECIMAL(10,2),
  FOREIGN KEY (magasin_id) REFERENCES magasins(magasin_id)
);





















